const cp = $input.first()?.json || {};
const nowMs = Date.now();
const startDatetime = cp.cursorStartDatetime || new Date(nowMs - 30 * 86400 * 1000).toISOString();
const endDatetime = new Date(nowMs + 5 * 60 * 1000).toISOString();
const advanceCursorTo = new Date(nowMs).toISOString();
const pageOffsets = cp.backfillCompleted ? [0, 50] : [0, 50, 100, 150];
return pageOffsets.map(offset => ({
  json: {
    startDatetime,
    endDatetime,
    advanceCursorTo,
    limit: 50,
    offset
  }
}));

const pages = $input.all();
const seen = new Set();
const attempts = [];
for (const page of pages) {
  const list = Array.isArray(page.json?.items) ? page.json.items : [];
  for (const item of list) {
    if (!item || !item.attempt_id) continue;
    if (item.channel_direction !== 'inbound' && item.channel_direction !== 'outbound') continue;
    const key = `${item.channel_direction}:${item.interaction_id || item.attempt_id}`;
    if (seen.has(key)) continue;
    seen.add(key);
    attempts.push(item);
  }
}
if (attempts.length === 0) {
  return [{
    json: {
      emptyBatch: true,
      advanceCursorTo: $('Build Paginated Offsets').first().json.advanceCursorTo
    }
  }];
}
return attempts.map(attempt => ({
  json: {
    emptyBatch: false,
    attempt,
    needsTranscript: Boolean(attempt.connectivity_status === 'connected' && attempt.interaction_id),
    encodedInteractionId: attempt.interaction_id ? encodeURIComponent(attempt.interaction_id) : ''
  }
}));

const connectedInputs = $('Has Connected Transcript?').all(0);
const txOutputs = $input.all();
const paired = [];
for (let i = 0; i < connectedInputs.length; i++) {
  const attempt = connectedInputs[i]?.json?.attempt;
  const tx = txOutputs[i]?.json;
  if (!attempt) continue;
  paired.push({
    json: {
      attempt,
      messages: Array.isArray(tx?.messages) ? tx.messages : []
    }
  });
}
return paired;

const nonConnected = $input.all().filter(x => !x.json?.emptyBatch && x.json?.attempt);
return nonConnected.map(x => ({
  json: {
    attempt: x.json.attempt,
    messages: []
  }
}));

const allItems = $input.all();
const advanceCursorTo = $('Build Paginated Offsets').first().json.advanceCursorTo;
const calls = [];
for (const item of allItems) {
  const a = item.json?.attempt;
  if (!a || !a.attempt_id) continue;
  const av = a.agent_variables && typeof a.agent_variables === 'object' ? a.agent_variables : {};
  const messages = Array.isArray(item.json?.messages)
    ? item.json.messages.slice(0, 200).map(m => ({
        role: String(m.role || 'user'),
        content: typeof m.content === 'string' ? m.content.slice(0, 4000) : '',
        ...(typeof m.english_content === 'string' ? { english_content: m.english_content.slice(0, 4000) } : {}),
        ...(typeof m.language_name === 'string' ? { language_name: m.language_name.slice(0, 64) } : {}),
        ...(m.turn_id !== undefined ? { turn_id: m.turn_id } : {})
      }))
    : [];
  calls.push({
    attemptId: String(a.attempt_id),
    interactionId: a.interaction_id || null,
    direction: a.channel_direction === 'inbound' ? 'inbound' : 'outbound',
    connectivityStatus: ['connected', 'no_answer', 'busy', 'failed'].includes(a.connectivity_status) ? a.connectivity_status : 'unknown',
    failureReason: a.failure_reason || null,
    endedBy: a.ended_by || null,
    durationSeconds: typeof a.duration_in_seconds === 'number' ? a.duration_in_seconds : null,
    startDatetime: a.start_datetime || null,
    endDatetime: a.end_datetime || null,
    attemptedAt: a.attempted_at || null,
    userContact: a.user_contact || null,
    userContactMasked: a.user_contact_masked || null,
    recordingAvailable: Boolean(a.audio_url && a.interaction_id),
    appVersion: a.app_version ?? null,
    languageName: a.language_name || null,
    agentVariables: {
      user_name: av.user_name ?? null,
      call_purpose: av.call_purpose ?? null,
      call_summary: av.call_summary ?? null,
      business_name: av.business_name ?? null,
      service_needed: av.service_needed ?? null,
      preferred_callback_time: av.preferred_callback_time ?? null
    },
    messages
  });
}
const batches = [];
for (let i = 0; i < Math.max(1, calls.length); i += 50) {
  const slice = calls.slice(i, i + 50);
  const isLast = i + 50 >= calls.length;
  batches.push({
    json: {
      calls: slice,
      advanceCursorTo: isLast ? advanceCursorTo : null,
      markBackfillCompleted: isLast
    }
  });
}
return batches;
